with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'تشغيل أنظمة الإنذار المبكر متعددة المخاطر','خرائط المخاطر والإنذار بالفيضانات والحر والجفاف والغبار والمخاطر الساحلية والجوية وتصميم الرسائل وتقييم الفاعلية.',29,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تشغيل أنظمة الإنذار متعددة المخاطر',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التواصل والتحقق من الإنذار',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('multi-hazard-risk-mapping','خرائط المخاطر متعددة الظواهر وتحديد مناطق الأولوية','دمج خرائط الخطر والتعرض والهشاشة في منتجات مكانية.','{"blocks":[{"type":"text","text":"توضح خريطة الخطر التوزيع المكاني لظاهرة أو شدة محتملة، بينما تضيف خريطة المخاطر معلومات التعرض والهشاشة."},{"type":"text","text":"تحتاج الخرائط إلى تعريف واضح للظاهرة والعتبة والفترة الزمنية ومقياس المكان."},{"type":"text","text":"قد تشمل طبقات الخطر خرائط الهطول الشديد والرياح والحرارة والفيضانات والعواصف الساحلية."},{"type":"text","text":"تشمل طبقات التعرض السكان والمباني والطرق والمستشفيات ومصادر المياه والبنية التحتية."},{"type":"text","text":"تستخدم مؤشرات الهشاشة والقدرة على الاستجابة لفهم اختلاف التأثير بين المناطق."},{"type":"text","text":"يجب توحيد الإسقاط المكاني والدقة والحدود الإدارية ومصادر البيانات قبل دمج الطبقات."},{"type":"text","text":"تؤثر أوزان المؤشرات وطريقة تجميعها في التصنيف النهائي للمخاطر."},{"type":"text","text":"قد تخفي الخرائط المركبة التفاصيل، لذلك يفضل إظهار المكونات الأساسية إلى جانب النتيجة."},{"type":"text","text":"يجب توثيق تاريخ البيانات وحدودها وعدم اليقين وطريقة الاستيفاء المكاني."},{"type":"text","text":"تراجع الخرائط مع الجهات المحلية للتحقق من ملاءمة المواقع والتعرض والبيانات."},{"type":"text","text":"مثال: قد تتقاطع منطقة هطول غزير مع حوض سريع الاستجابة وطريق رئيسي، فتظهر أولوية متابعة مختلفة عن منطقة غير مأهولة."},{"type":"callout","text":"خلاصة: خريطة المخاطر منتج متعدد الطبقات يجب أن يكون قابلاً للتفسير والتحديث."}]}',2160,55,'["تمييز خريطة الخطر عن خريطة المخاطر","دمج الطبقات المكانية","تحديد حدود المنتج"]','تشغيل أنظمة الإنذار متعددة المخاطر'),
('flood-early-warning-operations','التشغيل العملي للإنذار المبكر بالفيضانات','سلسلة الرصد المطري والهيدرولوجي والتنبؤ وإصدار التحذير.','{"blocks":[{"type":"text","text":"يبدأ الإنذار المبكر بالفيضانات بمراقبة الهطول والتدفقات ومناسيب الأنهار وحالة الأحواض."},{"type":"text","text":"تحتاج المراكز إلى بيانات مطر آنية ومحطات منسوب وتصريف ومعلومات عن رطوبة التربة."},{"type":"text","text":"تستخدم توقعات الطقس لتقدير المطر القادم، ثم تدخل النتائج في نماذج تحويل المطر إلى جريان."},{"type":"text","text":"تستخدم نماذج التوجيه النهري لتقدير توقيت الذروة ومقدار التدفق ومناطق الانتشار المحتملة."},{"type":"text","text":"يجب التمييز بين إنذار السيول المفاجئة في الأحواض الصغيرة وإنذار الفيضانات النهرية الأبطأ."},{"type":"text","text":"تحدد مهلة الإنذار من زمن وصول البيانات وتشغيل النماذج ومراجعة المنتج وتوزيعه."},{"type":"text","text":"تتأثر جودة الإنذار بحالة الحوض السابقة والتخزين والتربة والتغيرات في المجرى والمنشآت."},{"type":"text","text":"تستخدم عتبات محلية لمناسيب أو تدفقات أو آثار متوقعة، مع مراجعتها بناء على السجلات."},{"type":"text","text":"يجب توضيح المنطقة والفترة ومستوى الثقة والأثر المحتمل في الرسالة."},{"type":"text","text":"تراجع الإنذارات بعد الحدث بمقارنة التوقعات بالمنسوب والتدفق والآثار الفعلية."},{"type":"text","text":"مثال: قد يصدر إنذار سيول لحوض صغير بناءً على هطول متوقع شديد حتى قبل ظهور ارتفاع واضح في النهر."},{"type":"callout","text":"خلاصة: الإنذار بالفيضانات يعتمد على دمج التنبؤ الجوي والهيدرولوجي وسرعة الاتصال."}]}',2170,55,'["شرح سلسلة الإنذار بالفيضانات","دمج التوقع الجوي والهيدرولوجي","تحديد مهلة الإنذار"]','تشغيل أنظمة الإنذار متعددة المخاطر'),
('heat-health-warning-operations','تشغيل التحذيرات من موجات الحر والمخاطر الصحية','مراقبة الإجهاد الحراري والمدة الليلية والفئات والمناطق المعرضة.','{"blocks":[{"type":"text","text":"تبدأ مراقبة موجات الحر بتحديد العتبات الحرارية المحلية والفترة المرجعية والمدة اللازمة لاعتبار الحدث موجة حر."},{"type":"text","text":"قد تشمل المؤشرات درجات الحرارة القصوى والدنيا ومؤشر الحرارة أو مؤشرات الإجهاد الحراري المعتمدة."},{"type":"text","text":"تؤثر الرطوبة والرياح والإشعاع والظل في الإحساس الحراري، لذلك لا تكفي الحرارة الجافة وحدها في كل الحالات."},{"type":"text","text":"يجب متابعة درجات الحرارة الليلية لأن ضعف التبريد الليلي قد يزيد العبء الحراري المتراكم."},{"type":"text","text":"تؤثر الجزر الحرارية الحضرية والغطاء النباتي وكثافة العمران في التوزيع المكاني للتعرض."},{"type":"text","text":"تستخدم التوقعات متعددة الأيام لتحديد بداية الموجة وذروتها ومدتها وانحسارها."},{"type":"text","text":"ينبغي ربط التحذير بالمعلومات الصحية الرسمية المعتمدة محلياً دون تقديم تشخيص طبي."},{"type":"text","text":"تحدد الجهات المعنية الفئات والخدمات الحساسة وفق البيانات المتاحة والخصوصية والحوكمة."},{"type":"text","text":"يجب أن تشرح الرسالة مستوى الخطر والفترة والمناطق والإجراءات الرسمية الموصى بها."},{"type":"text","text":"تراجع التحذيرات بمقارنة المؤشرات المتوقعة بالقياسات والآثار الصحية والطلب على الخدمات."},{"type":"text","text":"مثال: موجة حر ذات ليالٍ دافئة متتالية قد تتطلب متابعة مختلفة عن يوم واحد شديد الحرارة."},{"type":"callout","text":"خلاصة: التحذير الحراري يجمع المؤشرات الجوية والمدة والتعرض والتنسيق الصحي."}]}',2180,55,'["اختيار مؤشر حراري مناسب","تحديد مدة الموجة","ربط التحذير بالتأثير"]','تشغيل أنظمة الإنذار متعددة المخاطر'),
('drought-early-warning-and-seasonal-monitoring','الإنذار المبكر بالجفاف ومراقبة الموسم','مراقبة الهطول والطلب التبخري ورطوبة التربة والمخزون المائي.','{"blocks":[{"type":"text","text":"يهدف الإنذار المبكر بالجفاف إلى اكتشاف تدهور الظروف المائية قبل تحولها إلى آثار واسعة على الزراعة والمياه."},{"type":"text","text":"تستخدم مؤشرات الهطول مثل SPI لتقييم النقص على مدد زمنية مختلفة."},{"type":"text","text":"تستخدم مؤشرات تجمع الهطول والطلب التبخري مثل SPEI لتقييم جانب من العجز المناخي المائي."},{"type":"text","text":"تساعد رطوبة التربة والغطاء النباتي في تقييم الجفاف الزراعي، بينما تساعد التدفقات والخزانات في تقييم الجفاف الهيدرولوجي."},{"type":"text","text":"تحتاج المراقبة إلى خط أساس مناخي واضح وسجلات طويلة ومتجانسة."},{"type":"text","text":"قد تتأخر استجابة الأنهار والمياه الجوفية عن تحسن الهطول، لذلك لا ينتهي الجفاف بكل حدث مطري."},{"type":"text","text":"تستخدم التوقعات الموسمية لتقدير احتمالات استمرار النقص أو تحسنه، مع توضيح عدم اليقين."},{"type":"text","text":"تحدد مراحل المتابعة والإنذار وفق عتبات متفق عليها بين الأرصاد والمياه والزراعة والجهات المختصة."},{"type":"text","text":"ينبغي ربط المؤشرات بالأثر القطاعي والطلب المائي وحالة المخزون."},{"type":"text","text":"تراجع دقة الإنذار عبر مقارنة المؤشرات بالتطور الفعلي للموسم والآثار المرصودة."},{"type":"text","text":"مثال: تحسن مؤشر المطر قصير الأمد قد لا يعني تعافي التربة أو الخزانات بعد موسم جفاف طويل."},{"type":"callout","text":"خلاصة: إنذار الجفاف نظام مراقبة متكامل متعدد المؤشرات والمدد والقطاعات."}]}',2190,55,'["اختيار مؤشرات الجفاف","دمج الأرصاد والهيدرولوجيا","تحديد مراحل الإنذار"]','تشغيل أنظمة الإنذار متعددة المخاطر'),
('dust-and-air-quality-warning-operations','تشغيل التحذيرات من الغبار وتدهور جودة الهواء','دمج توقع الرياح والغبار وقياسات الجسيمات والرؤية.','{"blocks":[{"type":"text","text":"تحتاج تحذيرات الغبار إلى تحديد مصدر الجسيمات ومسار النقل وارتفاع الطبقة ومدى وصولها إلى السطح."},{"type":"text","text":"تستخدم خرائط الرياح والرطوبة وصور الأقمار ومنتجات الهباء لتوقع مناطق انتقال الغبار."},{"type":"text","text":"تستخدم محطات PM10 وPM2.5 والرؤية لتقييم تركيز الجسيمات والأثر قرب السطح."},{"type":"text","text":"قد يكون الغبار مرتفعاً فوق سطح الأرض دون أن يعكس التركيز السطحي، لذلك تدمج المنتجات الفضائية مع القياسات الأرضية."},{"type":"text","text":"تؤثر الجبهات والهبّات والرياح المحلية في تغير مفاجئ لمناطق الغبار واتجاهه."},{"type":"text","text":"يجب التمييز بين الغبار الصحراوي والدخان والملوثات الحضرية لأن مصادرها وخصائصها تختلف."},{"type":"text","text":"تحدد عتبات التحذير وفق المعايير الصحية والبيئية الرسمية المعتمدة محلياً."},{"type":"text","text":"توضح الرسالة المناطق والفترة المتوقعة وشدة انخفاض الرؤية أو ارتفاع الجسيمات عند توافر البيانات."},{"type":"text","text":"ينبغي تنسيق التحذير مع الجهات الصحية والبيئية والنقل وفق المسؤوليات المعتمدة."},{"type":"text","text":"تراجع جودة الإنذار بمقارنة التوقعات ببيانات المحطات وتقارير الرؤية والصور الفضائية."},{"type":"text","text":"مثال: قد تصل سحابة غبار مرتفعة إلى المنطقة قبل وصول التركيزات السطحية، ولذلك يفيد الفصل بين زمن وصول الطبقة وزمن التأثير الأرضي."},{"type":"callout","text":"خلاصة: تحذير الغبار يحتاج ربط النقل الجوي بالقياسات الأرضية والتواصل متعدد الجهات."}]}',2200,55,'["تمييز الغبار المحمول عن التلوث المحلي","دمج الرؤية والجسيمات","صياغة تحذير واضح"]','تشغيل أنظمة الإنذار متعددة المخاطر'),
('coastal-hazard-warning-systems','أنظمة الإنذار من المخاطر الساحلية والبحرية','دمج الرياح والأمواج والمد والضغط وارتفاع مستوى البحر.','{"blocks":[{"type":"text","text":"تنشأ المخاطر الساحلية من تفاعل الرياح والأمواج والمد الفلكي والمد العاصفي وشكل الساحل."},{"type":"text","text":"تستخدم توقعات الرياح البحرية لتقدير نمو الأمواج واتجاهها وفترتها."},{"type":"text","text":"يسهم انخفاض الضغط واندفاع الرياح نحو الساحل في ارتفاع مستوى البحر فوق المد الفلكي."},{"type":"text","text":"قد يؤدي تزامن المد العاصفي مع مد فلكي مرتفع إلى زيادة مستوى المياه الساحلية."},{"type":"text","text":"تؤثر الأعماق البحرية وشكل الخلجان والجرف القاري في تضخيم الأمواج أو تغير اتجاهها."},{"type":"text","text":"تستخدم العوامات ومقاييس المد والأقمار والنماذج البحرية لتقدير الحالة."},{"type":"text","text":"يجب الفصل بين ارتفاع الموج وارتفاع مستوى البحر والمد العاصفي عند إصدار المنتج."},{"type":"text","text":"تحدد المناطق الساحلية الأكثر تعرضاً وفق الارتفاع والتضاريس والبنية والخدمات."},{"type":"text","text":"ينبغي أن توضح الرسالة الفترة والموقع ونوع الخطر ومستوى الثقة ومصدر التوقع."},{"type":"text","text":"تحتاج التحذيرات إلى تنسيق مع سلطات الموانئ والنقل البحري وإدارة السواحل."},{"type":"text","text":"مثال: أمواج مرتفعة وحدها قد لا تسبب غمراً واسعاً، لكن تزامنها مع مد مرتفع واندفاع بحري يزيد الخطر."},{"type":"callout","text":"خلاصة: الإنذار الساحلي متعدد المتغيرات ويحتاج نمذجة جوية وبحرية ومعلومات مكانية."}]}',2210,55,'["تحديد مكونات الخطر الساحلي","فهم تراكب المد والأمواج","بناء رسالة تحذير بحرية"]','تشغيل أنظمة الإنذار متعددة المخاطر'),
('aviation-weather-hazard-warning','التحذير من مخاطر الطيران الجوية','متابعة الاضطراب والجليد والعواصف وقص الرياح والرماد البركاني.','{"blocks":[{"type":"text","text":"تتطلب سلامة الطيران معلومات دقيقة عن الظواهر الجوية التي قد تؤثر في الطائرات والمطارات والمسارات."},{"type":"text","text":"تشمل المخاطر الاضطراب والجليد والعواصف الرعدية وقص الرياح والرماد البركاني والرؤية المنخفضة."},{"type":"text","text":"تستخدم تقارير المطارات والنشرات الجوية وبيانات الطائرات والرادار والأقمار لتشخيص الحالة."},{"type":"text","text":"تختلف المخاطر حسب مستوى الطيران ومرحلة الرحلة والارتفاع والموقع."},{"type":"text","text":"تستخدم نشرات SIGMET وغيرها وفق نطاقها وتعريفها التشغيلي لإبلاغ الظواهر المؤثرة."},{"type":"text","text":"تحتاج معلومات الاضطراب إلى تحديد الارتفاع والمنطقة والمدة والشدة وفق المصطلحات المعتمدة."},{"type":"text","text":"تحتاج تحذيرات الجليد إلى معلومات عن السحب والحرارة والقطيرات فائقة التبريد والارتفاع."},{"type":"text","text":"يؤثر قص الرياح قرب المدرج في عمليات الإقلاع والهبوط ويحتاج رصداً وتوقعاً محلياً مناسباً."},{"type":"text","text":"يجب الالتزام بمواصفات الترميز والتوقيت والتحديث المعتمدة في منتجات الطيران."},{"type":"text","text":"تراجع التحذيرات بعد الحالة بمقارنتها بتقارير الطائرات والمطارات والبيانات الرصدية."},{"type":"text","text":"مثال: تغير مستوى الاضطراب مع الارتفاع يستدعي تحديد الطبقة المتأثرة لا الاكتفاء بوصف عام للمنطقة."},{"type":"callout","text":"خلاصة: تحذير الطيران منتج تخصصي يتطلب دقة المصطلحات والمكان والارتفاع والتوقيت."}]}',2220,55,'["تحديد مخاطر الطيران","فهم مستويات التحذير","تمييز المنتجات التشغيلية"]','تشغيل أنظمة الإنذار متعددة المخاطر'),
('severe-convective-warning-nowcasting','الإنذار الآني بالعواصف الحملية الشديدة','دمج مؤشرات الرادار والبرق والسبر والتطور السريع للعواصف.','{"blocks":[{"type":"text","text":"يركز الإنذار الآني على رصد العواصف النشطة وتغيرها خلال مدد قصيرة باستخدام بيانات عالية التواتر."},{"type":"text","text":"تستخدم الانعكاسية والسرعة الشعاعية والمنتجات القطبية لتقييم بنية العاصفة والهطول والحركة."},{"type":"text","text":"تستخدم بيانات البرق لمراقبة النشاط الكهربائي والتغيرات السريعة داخل العاصفة."},{"type":"text","text":"تساعد صور الأقمار في رصد نمو قمم السحب والتبريد السريع والتطور الحملي."},{"type":"text","text":"توفر ملفات السبر والبيئة العددية معلومات عن الاستقرار والرطوبة والقص قبل تطور العاصفة."},{"type":"text","text":"تحدد مهلة الإنذار وفق سرعة العاصفة ووقت اكتشافها ووقت إيصال الرسالة."},{"type":"text","text":"قد تتغير منطقة الخطر بسرعة بسبب حركة الخلايا أو تجددها أو اندماجها."},{"type":"text","text":"ينبغي تحديث نطاق التحذير عند تغير المسار أو الشدة أو انتهاء الخطر في بعض المناطق."},{"type":"text","text":"يجب التمييز بين المؤشرات الرادارية الاستدلالية والتأكيد الأرضي للظاهرة."},{"type":"text","text":"تراجع جودة الإنذار بمقارنة وقت الإصدار والمهلة وموقع الظاهرة وشدتها المرصودة."},{"type":"text","text":"مثال: ظهور إشارة دوران متزايدة مع نمو انعكاسية وبرق يستدعي دمج المؤشرات قبل تعديل التحذير."},{"type":"callout","text":"خلاصة: الإنذار الحملي عملية متكررة تعتمد على الرصد الآني وتحديث القرار."}]}',2230,55,'["تحديد مؤشرات تطور العاصفة","تقدير مهلة الإنذار","تحديث نطاق التحذير"]','تشغيل أنظمة الإنذار متعددة المخاطر'),
('impact-based-warning-message-design','تصميم رسالة التحذير القائمة على التأثير','صياغة الرسالة والمكان والفترة والاحتمال والإجراء المطلوب.','{"blocks":[{"type":"text","text":"تبدأ رسالة التحذير بتحديد الظاهرة والمناطق والفترة الزمنية المتأثرة."},{"type":"text","text":"يجب أن يكون عنوان الرسالة واضحاً ويعكس مستوى الخطر وفق النظام المعتمد."},{"type":"text","text":"تشرح الرسالة الأثر المحتمل على الطرق والمياه والزراعة والصحة والخدمات بحسب نوع الحدث."},{"type":"text","text":"تستخدم لغة احتمالية دقيقة عندما يكون توقيت الحدث أو موقعه أو شدته غير مؤكد."},{"type":"text","text":"يجب الفصل بين ما تم رصده فعلياً وما يتوقع حدوثه لاحقاً."},{"type":"text","text":"تحدد الرسالة وقت الإصدار ووقت الانتهاء أو موعد التحديث المتوقع."},{"type":"text","text":"تستخدم أسماء مناطق وحدوداً جغرافية مفهومة للجمهور والجهات المستفيدة."},{"type":"text","text":"تتجنب الرسالة المصطلحات الفنية غير المشروحة والمبالغة التي تضعف الثقة."},{"type":"text","text":"ينبغي تضمين الإجراء الرسمي الموصى به من الجهة المختصة، لا اختراع إرشادات غير معتمدة."},{"type":"text","text":"تحتاج الرسائل إلى قنوات متعددة وصيغ مناسبة لذوي الاحتياجات المختلفة."},{"type":"text","text":"مثال: رسالة مطر شديد توضح المناطق والفترة واحتمال الهطول وأثره المحتمل على الأحواض والطرق."},{"type":"callout","text":"خلاصة: التحذير الجيد مختصر ودقيق ومحدد الأثر والوقت والمكان ومصدره موثوق."}]}',2240,55,'["بناء عناصر الرسالة","شرح الاحتمال والأثر","تجنب الغموض والتضارب"]','التواصل والتحقق من الإنذار'),
('early-warning-system-performance-evaluation','تقييم أداء أنظمة الإنذار المبكر وفاعليتها','قياس التغطية والمهلة والوصول والفهم والاستجابة والتحسين.','{"blocks":[{"type":"text","text":"لا يقاس نجاح الإنذار المبكر بدقة التنبؤ وحدها، بل بقدرة النظام على تحويل المعلومة إلى استجابة مناسبة."},{"type":"text","text":"تشمل مؤشرات الأداء دقة التنبؤ والمهلة الزمنية والتغطية المكانية واستمرارية الرصد."},{"type":"text","text":"يقاس وصول الرسالة عبر القنوات والجمهور والجهات المستفيدة في الوقت المناسب."},{"type":"text","text":"يحتاج فهم الرسالة إلى تقييم وضوح اللغة والمناطق والفترة والإجراء المقصود."},{"type":"text","text":"تؤثر الثقة بالمصدر وتكرار الإنذارات وجودة الاتصال في استجابة المستخدمين."},{"type":"text","text":"تراجع جاهزية المؤسسات وخطط الاستجابة وتوزيع المسؤوليات إلى جانب أداء التنبؤ."},{"type":"text","text":"تساعد التمارين والمحاكاة على اختبار تدفق البيانات وإصدار التحذير وتلقيه والاستجابة له."},{"type":"text","text":"تستخدم مراجعات ما بعد الحدث لتحديد نقاط الفشل والنجاح في كل مرحلة من سلسلة الإنذار."},{"type":"text","text":"ينبغي تفصيل الأداء حسب المناطق والفئات والظواهر حتى لا يخفي المتوسط العام فجوات التغطية."},{"type":"text","text":"تترجم نتائج التقييم إلى خطة تحسين لها مسؤوليات ومواعيد ومؤشرات متابعة."},{"type":"text","text":"مثال: قد يكون التنبؤ دقيقاً لكن التحذير لا يصل إلى القرى النائية؛ لذلك يفشل النظام رغم نجاح النموذج."},{"type":"callout","text":"خلاصة: فاعلية الإنذار منظومة اجتماعية وتقنية ومؤسسية تبدأ بالرصد وتنتهي بالاستجابة والتعلم."}]}',2250,55,'["تحديد مؤشرات أداء النظام","قياس وصول الرسالة وفهمها","إجراء تقييم شامل"]','التواصل والتحقق من الإنذار'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'تشغيل أنظمة الإنذار متعددة المخاطر' then u1.id when 'التواصل والتحقق من الإنذار' then u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'تشغيل أنظمة الإنذار المبكر متعددة المخاطر',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;